import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        raise ValueError("Empty duration string")
    total = 0
    pos = 0
    for match in re.finditer(r'(\d+)([hms])', s):
        if match.start() != pos:
            raise ValueError(f"Invalid input at position {pos}")
        value = int(match.group(1))
        unit = match.group(2)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value
        pos = match.end()
    if pos != len(s):
        raise ValueError(f"Invalid trailing content at position {pos}")
    return total
